// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota // = 2
	Framed                        // = 4
	HTTP                          // = 8
	GRPC                          // = 16
	HESSIAN2                      // = 32
	TTHeaderStreaming             // = 64 (dedicated, not composite)
	GRPCStreaming                 // = 128 (new dedicated gRPC streaming protocol)

	TTHeaderFramed = TTHeader | Framed
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Handle common single-value cases first for performance
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	}

	// Handle composite values by listing all set flags
	var parts []string
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "HESSIAN2")
	}
	if tp&TTHeaderStreaming != 0 {
		parts = append(parts, "TTHeaderStreaming")
	}
	if tp&GRPCStreaming != 0 {
		parts = append(parts, "GRPCStreaming")
	}

	if len(parts) > 0 {
		return parts[0] + "|" + joinParts(parts[1:])
	}
	return Unknown
}

func joinParts(parts []string) string {
	if len(parts) == 0 {
		return ""
	}
	result := parts[0]
	for i := 1; i < len(parts); i++ {
		result += "|" + parts[i]
	}
	return result
}
