// readAndCheckFrameHeader reads a frame header from the reader and validates it.
// If the frame header is malformed, it includes a hex dump of the bytes in the error message.
func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}

	// Parse the frame header
	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
	}

	// Validate frame type
	if fh.Type > http2.FrameContinuation {
		return http2.FrameHeader{}, fmt.Errorf("http2: invalid frame type %d, frame header bytes: %02x", fh.Type, buf)
	}

	return fh, nil
}

